import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {spawnSync} from 'node:child_process';import assert from 'node:assert/strict';
const candidate='tmp/g1-release',base='https://reservation-system-staging-staging.up.railway.app';
const manifestPath=process.argv[2]??'docs/g3-03-account-link-candidate-2026-09-22.json';
const outputPath=process.argv[3]??'docs/g3-03-bundle-refresh-2026-09-22.json';
if(!/^docs\/[a-z0-9-]+\.json$/.test(manifestPath)||!/^docs\/[a-z0-9-]+\.json$/.test(outputPath))throw Error('Manifest and output must be named JSON files in docs');
const result=spawnSync('powershell.exe',['-NoProfile','-Command','railway variables --json -p 09914d62-2d30-4e30-bca8-3d0a718f24be -e staging -s a2a21779-4078-4a8b-b841-438f0ef52d7c'],{encoding:'utf8',windowsHide:true});
assert.equal(result.status,0,'Cannot read staging configuration; raw output intentionally suppressed');
let env;try{env=JSON.parse(result.stdout);}catch{throw Error('Invalid staging configuration response');}
assert.equal(new URL(env.NEXT_PUBLIC_SUPABASE_URL).hostname,'ongjsegewpnbkqugrpom.supabase.co');
const keys=['SUPABASE_SERVICE_ROLE_KEY','CRON_SECRET','BROWSER_BOOKING_SECRET','REGISTRATION_TOKEN_SECRET','LINE_CHANNEL_SECRET','LINE_CHANNEL_ACCESS_TOKEN','LINE_CHANNEL_SECRETS_JSON','LINE_CHANNEL_ACCESS_TOKENS_JSON','ECPAY_HASH_KEY','ECPAY_HASH_IV','NEWEBPAY_HASH_KEY','NEWEBPAY_HASH_IV','RESEND_API_KEY'];
const secrets=keys.flatMap(k=>typeof env[k]==='string'&&env[k].length>=8?[[k,env[k]]]:[]);assert.ok(secrets.some(([k])=>k==='SUPABASE_SERVICE_ROLE_KEY'));
for(const key of ['LINE_CHANNEL_SECRETS_JSON','LINE_CHANNEL_ACCESS_TOKENS_JSON'])if(env[key]){try{for(const v of Object.values(JSON.parse(env[key])))if(typeof v==='string'&&v.length>=8)secrets.push([key+' entry',v]);}catch{throw Error('Invalid channel map; raw configuration suppressed');}}
const findings=[],artifacts=[];const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
function scan(label,text){for(const[k,v]of secrets)if(text.includes(v)||text.includes(encodeURIComponent(v)))findings.push({path:label,kind:'configured-secret',key:k});for(const m of text.matchAll(/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g)){try{if(JSON.parse(Buffer.from(m[0].split('.')[1],'base64url')).role==='service_role')findings.push({path:label,kind:'service-role-jwt'});}catch{}}if(/-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/.test(text))findings.push({path:label,kind:'private-key'});artifacts.push({path:label,bytes:Buffer.byteLength(text),sha256:hash(text)});}
function walk(dir){return fs.readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(dir,e.name)):[path.join(dir,e.name)]);}
const manifest=JSON.parse(fs.readFileSync(manifestPath));for(const f of manifest.files)assert.equal(hash(fs.readFileSync(candidate+'/'+f.path)),f.sha256);
const chunks=walk(candidate+'/.next/static').filter(p=>/\.(js|map)$/.test(p));for(const p of chunks)scan('local:'+path.relative(candidate,p).replaceAll('\\','/'),fs.readFileSync(p,'utf8'));
const routes=['/','/book','/book/browser','/book/browser/my','/book/browser/reschedule','/book/reschedule','/register','/register/my','/register/pay','/register/cancel','/membership','/my','/payment/result','/embed/book','/embed/register','/admin/login','/line/account-link'];const urls=new Set();
for(const route of routes){const r=await fetch(base+route+'?clinic_slug=demo-beauty',{signal:AbortSignal.timeout(30000)});assert.equal(r.status,200,route);const text=await r.text();scan('live:'+route,text);for(const m of text.matchAll(/<script\b[^>]*\bsrc="([^"]+)"/g)){const u=new URL(m[1].replaceAll('&amp;','&'),base);if(u.origin===base&&u.pathname.startsWith('/_next/static/'))urls.add(u.href);}}
let authenticatedAssetPaths=0,authenticatedRoutes=0;
if(process.argv[4]){const assetListPath=process.argv[4];if(!/^docs\/[a-z0-9-]+\.json$/.test(assetListPath))throw Error('Asset list must be a named JSON file in docs');const assetList=JSON.parse(fs.readFileSync(assetListPath));assert.ok(Array.isArray(assetList.routes)&&Array.isArray(assetList.assetPaths));authenticatedRoutes=assetList.routes.length;for(const assetPath of assetList.assetPaths){if(typeof assetPath!=='string'||!/^\/_next\/static\/[a-zA-Z0-9/_-]+\.js$/.test(assetPath)||assetPath.includes('..'))throw Error('Invalid authenticated asset path');urls.add(new URL(assetPath,base).href);authenticatedAssetPaths++;}}
for(const url of urls){const r=await fetch(url,{signal:AbortSignal.timeout(30000)});assert.equal(r.status,200);scan('live:'+new URL(url).pathname,await r.text());}
const out={capturedAt:new Date().toISOString(),candidateManifest:manifestPath,candidateFiles:manifest.fileCount,candidateHashesMatched:true,base,configuredSecretNamesChecked:[...new Set(secrets.map(([k])=>k))],missingSecretNames:keys.filter(k=>!secrets.some(([key])=>key===k)),localJsAndMaps:chunks.length,liveHtml:routes.length,authenticatedRoutes,authenticatedAssetPaths,liveScripts:urls.size,findings,artifacts,limitations:['Vault secret values not read','Live scan covers scripts linked by sampled public pages and observed admin pages, not every lazy or authenticated chunk','Local complete static directory is local build, not byte-identical Railway build','No authenticated customer payload or real LINE identity is exercised by this scanner']};
fs.writeFileSync(outputPath,JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({localJsAndMaps:out.localJsAndMaps,liveHtml:out.liveHtml,authenticatedRoutes:out.authenticatedRoutes,authenticatedAssetPaths:out.authenticatedAssetPaths,liveScripts:out.liveScripts,secretNamesChecked:out.configuredSecretNamesChecked,findings:out.findings}));assert.equal(findings.length,0);
